"""Render a real matplotlib.pyplot PNG in the Pyodide fallback."""

from io import BytesIO

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt


def evaluation_function(response, answer, params=None):
    """Return a small PNG generated by pyplot, not a mock render."""
    params = params or {}
    values = params.get("values", [0, 1, 4, 9])

    figure, axis = plt.subplots()
    try:
        axis.plot(range(len(values)), values)
        rendered = BytesIO()
        figure.savefig(rendered, format="png")
        png_bytes = rendered.tell()
    finally:
        plt.close(figure)

    return {
        "is_correct": png_bytes > 1_000,
        "png_bytes": png_bytes,
    }
